from collections import deque

def {{fn_name}}(grid, start, end):
    R, C = len(grid), len(grid[0])
    q = deque([(start[0], start[1], 0)])
    seen = {start}
    while q:
        r, c, d = q.popleft()
        if (r, c) == end: return d
        for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
            nr, nc = r+dr, c+dc
            if 0<=nr<R and 0<=nc<C and grid[nr][nc] != '#' and (nr,nc) not in seen:
                seen.add((nr,nc))
                q.append((nr, nc, d+1))
